'use strict';
const $ = s => document.querySelector(s), app = $('#app');
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num = n => Number(n ?? 0).toLocaleString('ru-RU', {maximumFractionDigits:2});
const delta = n => (n >= 0 ? '+' : '') + num(n);
const date = s => new Date(s).toLocaleString('ru-RU');
const cats = ['Транспорт','Экология','Соцсфера','Безопасность','Сервисы'];
const labels = ['Транспорт','Экология','Социальная сфера','Безопасность','Городские сервисы'];
const icons = ['↗','♧','▥','◇','⌘'];
const modes = {solo:'Одиночная игра',multiplayer:'Сетевая игра',local:'На одном компьютере',ai:'Против AI-бота'};
const statuses = {lobby:'Ожидание игроков',playing:'Игра идёт',scored:'AI анализирует',complete:'Завершена',cancelled:'Отменена',waiting_players:'Ожидание остальных',analyzing:'AI анализирует',analysis_failed:'Анализ не завершён'};
const indicators = ['Разгрузка дорог','Общественный транспорт','Озеленение','Качество воздуха','Школы и детсады','Первичная медпомощь','Безопасность улиц','Безопасность движения','Надёжность ЖКХ','Обращения жителей'];
let user = null, current = null, filter = '', editor = null, templates = [], editingID = 'default', roomSocket = null, timer = null, routeVersion = 0, busy = false, handoff = false;
function notice(message, success = false) { const n = $('#notice'); n.textContent = message; n.className = success ? 'success' : ''; n.hidden = !message; }
async function api(path, method = 'GET', body) {const r = await fetch('/api'+path,{method,headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const v=await r.json();if(!r.ok){const e=new Error(v.error||'Ошибка сервера');e.status=r.status;throw e;}return v;}
function pageHead(title,sub='',extra=''){return `<div class="pagehead"><div><span class="eyebrow">CITY MANAGEMENT / SIMULATION</span><h1>${esc(title)}</h1><p>${esc(sub)}</p></div>${extra}</div>`;}
function table(head,rows){return `<div class="table-wrap"><table><thead><tr>${head.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;}
function stat(value,label){return `<div><div class="number">${esc(value)}</div><div class="sub">${esc(label)}</div></div>`;}
function nav(){const links=user?[['home','Главная'],['rooms','Комнаты'],['leaderboard','Рейтинг'],['history','История игр'],['profile','Профиль'],...(user.role==='admin'?[['admin','Админ']]:[])]:[['home','Главная'],['login','Войти'],['register','Регистрация']];$('#nav').innerHTML=links.map(([id,label])=>`<a href="#${id}" class="${location.hash.startsWith('#'+id)?'active':''}">${label}</a>`).join('');}
function home(){app.innerHTML=`<section class="hero"><div><span class="eyebrow">5 РЕШЕНИЙ · 1 ГОРОД · ТВОЙ СЦЕНАРИЙ</span><h1>Город начинается<br>с <em>решения.</em></h1><p>Станьте акимом на пять часов. Распределите ограниченный бюджет, измените районы и узнайте, какой след оставит ваша стратегия.</p><a class="button primary" href="#${user?'rooms':'register'}">Начать игру &nbsp; ↗</a><p class="sub">100 условных единиц · 5 решений · 8 кварталов последствий</p></div><div class="city-art"><svg viewBox="0 0 520 390" role="img" aria-label="Иллюстрация города с Байтереком"><defs><linearGradient id="ground" x2="1" y2="1"><stop stop-color="#3d7767"/><stop offset="1" stop-color="#183a40"/></linearGradient></defs><path d="M20 282 250 160 502 282 266 385Z" fill="url(#ground)" stroke="#739c80"/><g fill="none" stroke="#83bba155"><path d="m65 300 230-120m-176 146 230-122M190 349 420 226M80 250l220 113m-162-145 222 113m-167-144 225 116"/></g><g stroke="#80b7a1" stroke-width="1.2"><path d="M76 261V158l44-22 40 21v103l-40 23Z" fill="#326665"/><path d="m120 136 0 147 40-23V157Z" fill="#245157"/><path d="M338 277V133l38-19 46 23v138l-44 22Z" fill="#3b7770"/><path d="m378 136 44 1v138l-44 22Z" fill="#28595d"/><path d="M163 307V215l32-16 38 20v94l-35 16Z" fill="#497e72"/><path d="m198 219 35 0v94l-35 16Z" fill="#2d5c5d"/><path d="M283 298V196l28-15 39 19v104l-36 17Z" fill="#487d6c"/></g><g stroke="#b2d5b4" stroke-width="3" opacity=".7"><path d="M87 177v65m14-71v79m31-89v99m214-106v105m16-113v122m28-124v115m17-108v99m-233-53v66m17-73v74m101-101v79m16-68v79"/></g><g stroke="#e2c989" fill="none"><path d="M237 265h41m-32 0 5-116m18 116-7-116m-17 19h25m-26 19h27m-27 22h28" stroke-width="4"/><circle cx="257" cy="116" r="34" fill="#d5bc76"/><path d="M223 116h68m-34-34v68m-22-59c-15 43 59 45 44 0m-43 51c-14-46 56-46 43 0" stroke="#a98951" stroke-width="1.5"/></g><g fill="#92bfa0"><circle cx="72" cy="283" r="9"/><circle cx="176" cy="350" r="10"/><circle cx="439" cy="285" r="11"/><circle cx="313" cy="347" r="8"/></g></svg><div class="art-label">ASTANA / URBAN STRATEGY LAB</div></div></section><div class="grid">${[['01','Исследуйте город','Пять районов и десять показателей. Найдите проблемы, которые действительно влияют на качество жизни.'],['02','Примите пять решений','Выбирайте меры, учитывайте стоимость, лаги, синергии и ограничения. Соперники получают те же условия.'],['03','Получите AI-разбор','Сильные решения, компромиссы, риски и проверенные альтернативы. Сохраните PDF, Word или JSON.']].map(([n,t,p])=>`<article class="card"><span class="eyebrow">${n} / МИССИЯ</span><h3>${t}</h3><p>${p}</p></article>`).join('')}</div><div class="section-title"><h2>Пять направлений развития</h2><span class="pill">Выше — лучше</span></div><div class="grid five">${labels.map((c,i)=>`<div class="card"><span class="number positive">${icons[i]}</span><h3>${c}</h3><p>${indicators[i*2]}<br>${indicators[i*2+1]}</p></div>`).join('')}</div>`;}
function auth(register){app.innerHTML=`<section class="panel auth"><span class="eyebrow">ВАШ ГОРОД ЖДЁТ</span><h2>${register?'Создать аккаунт':'С возвращением'}</h2><form id="auth-form" class="stack" data-mode="${register?'register':'login'}"><label>Логин<input name="name" autocomplete="username" required pattern="[a-zA-Z0-9_-]{3,32}" minlength="3" maxlength="32" placeholder="mayor_astana"></label><label>Пароль<input name="password" type="password" required minlength="12" maxlength="256" autocomplete="${register?'new-password':'current-password'}"></label><p class="small">Латинский логин, 3–32 символа. Пароль — минимум 12 символов.</p><button class="primary">${register?'Зарегистрироваться':'Войти'}</button></form><p class="small"><br><a href="#${register?'login':'register'}">${register?'Уже есть аккаунт? Войти':'Нет аккаунта? Зарегистрироваться'} ↗</a></p></section>`;}
async function rooms(){const list=await api('/rooms');app.innerHTML=pageHead('Комнаты','Каждый игрок управляет своей версией одного города.','<a class="button primary" href="#create">Создать комнату +</a>')+`<form id="join-form" class="row panel"><label>Код комнаты<input name="code" required maxlength="12" placeholder="a82f19c01d42"></label><button>Присоединиться ↗</button></form><div class="section-title"><h2>Ваши и открытые комнаты</h2><button data-action="refresh">Обновить</button></div><div class="grid">${list.map(r=>`<article class="card"><div class="row between"><span class="tag">ROOM / ${esc(r.id)}</span><span class="pill">${esc(statuses[r.status])}</span></div><h3>${esc(r.name||r.scenario.city)}</h3><p>${esc(r.scenario.city)} · ${esc(modes[r.mode])}<br>Создатель: ${esc(r.host)}<br>${date(r.created)}</p><div class="row between"><span>${r.players.length} / 8 игроков</span><span>${num(r.scenario.budget)} усл. ед.</span></div>${r.host===user.name||r.players.includes(user.name)?`<a class="button fullwidth" href="#room/${r.id}">Открыть →</a>`:`<button data-action="join" data-id="${r.id}">Присоединиться</button>`}</article>`).join('')||'<div class="empty">Пока нет комнат. Начните свою первую игру.</div>'}</div>`;}
function editorHTML(){if(!editor)return '';const field=(label,path,value,type='text')=>`<label>${label}<input data-edit="${path}" type="${type}" value="${esc(value)}" ${type==='number'?'step="any"':''}></label>`;return `<div class="editor"><div class="fields">${field('Название города','city',editor.city)}${field('Описание / происхождение','methodology',editor.methodology)}<label>Бюджет<input value="100 условных единиц" disabled></label></div><h3>Районы и показатели</h3><p class="small">Доли населения должны в сумме давать 1. Индикаторы от 0 до 100.</p>${editor.districts.map((d,i)=>`<details><summary>${esc(d.name)} · доля ${num(d.pop)}</summary><div class="fields">${field('Район',`districts.${i}.name`,d.name)}${field('Доля населения',`districts.${i}.pop`,d.pop,'number')}<label>Объекты / школы (по строке)<textarea data-facilities="${i}">${esc((d.facilities||[]).join('\n'))}</textarea></label><button type="button" data-action="remove-district" data-index="${i}" class="danger">Удалить район</button></div><div class="indicators">${editor.keys.map((k,j)=>field(`${k} · ${indicators[j]}`,`districts.${i}.v.${j}`,d.v[j],'number')).join('')}</div></details>`).join('')}<button type="button" data-action="add-district">Добавить район +</button><h3>Каталог мероприятий</h3><p class="small">Фиксированные пары синергий и несовместимостей привязаны к M1–M14. Новые ID получают только свои эффекты.</p>${editor.measures.map((m,i)=>`<details><summary>${esc(m.id)} · ${esc(m.name)} · ${m.cost} усл. ед.</summary><div class="fields">${field('ID',`measures.${i}.id`,m.id)}${field('Название',`measures.${i}.name`,m.name)}${field('Стоимость',`measures.${i}.cost`,m.cost,'number')}${field('Лаг (кварталы)',`measures.${i}.lag`,m.lag,'number')}<label>Направление<select data-edit="measures.${i}.category">${cats.map((c,j)=>`<option ${m.category===c?'selected':''} value="${c}">${labels[j]}</option>`).join('')}</select></label><label>Тип<select data-edit="measures.${i}.type"><option ${m.type==='Район'?'selected':''}>Район</option><option ${m.type==='Город'?'selected':''}>Город</option></select></label>${field('Источник (если есть)',`measures.${i}.source`,m.source||'')}<button type="button" data-action="remove-measure" data-index="${i}" class="danger">Удалить меру</button></div><div class="indicators">${editor.keys.map(k=>field(k,`measures.${i}.effects.${k}`,m.effects[k]||0,'number')).join('')}</div></details>`).join('')}<button type="button" data-action="add-measure">Добавить мероприятие +</button></div>`;}
async function create(){templates=await api('/cities');editor=structuredClone(templates[0].scenario);app.innerHTML=pageHead('Новая игра','Настройте режим и выберите исходный город.')+`<form id="create-form" class="panel stack"><div class="grid two"><label>Название комнаты<input name="name" maxlength="100" placeholder="Astana Challenge"></label><label>Режим<select name="mode" id="mode">${Object.entries(modes).map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select></label><label>Источник города<select name="source" id="source"><option value="template">Шаблон администратора</option><option value="manual">Создать вручную</option><option value="generated">Сгенерировать с AI</option></select></label><label id="template-label">Шаблон<select name="city_id" id="city-template">${templates.filter(t=>!t.archived).map(t=>`<option value="${t.id}">${esc(t.scenario.city)}</option>`).join('')}</select></label><label id="local-count" hidden>Игроков на одном компьютере<input name="players" type="number" min="2" max="8" value="2"></label></div><div id="ai-city" hidden><label>Описание учебного города<input id="city-theme" placeholder="Молодой город с перегруженным транспортом"></label><button type="button" data-action="generate-city">Сгенерировать город</button></div><div id="city-editor" hidden>${editorHTML()}</div><p class="small" id="source-note">${esc(editor.methodology)}</p><button class="primary">Создать игру →</button></form>`;}
async function openRoom(id){current=await api('/rooms/'+id);handoff=current.room.mode==='local';renderRoom();connectRoom(id);}
function connectRoom(id){roomSocket=new WebSocket(`${location.protocol==='https:'?'wss':'ws'}://${location.host}/api/rooms/${id}/ws`);roomSocket.onopen=()=>{$('#connection').textContent='● LIVE / WEBSOCKET';};roomSocket.onmessage=e=>{const msg=JSON.parse(e.data);const before=current?.room?.status;const picks=JSON.stringify(current?.picks);current=msg.data;if(before!==current.room.status||picks!==JSON.stringify(current.picks)||current.room.status==='lobby')renderRoom();};roomSocket.onclose=()=>{$('#connection').textContent='○ RECONNECT';if(location.hash==='#room/'+id)timer=setTimeout(()=>{api('/rooms/'+id).then(v=>{current=v;renderRoom();connectRoom(id);}).catch(e=>notice(e.message));},2500);};}
function districtCards(s,result){return `<div class="grid five">${s.districts.map((d,i)=>`<article class="panel district"><h3>${esc(d.name)}</h3><span class="sub">Доля населения: ${num(d.pop*100)}%</span>${s.keys.map((k,j)=>`<div class="indicator" title="${esc(indicators[j])}"><span>${esc(k)}</span><progress max="100" value="${result?result[i].after[j]:d.v[j]}"></progress><span>${num(result?result[i].after[j]:d.v[j])}</span></div>`).join('')}${(d.facilities||[]).length?`<details><summary>Объекты района</summary><p class="small">${d.facilities.map(esc).join('<br>')}</p></details>`:''}</article>`).join('')}</div>`;}
function renderRoom(){if(!current)return;const {room:r,actor:who}=current,s=r.scenario,picks=current.picks||[];if(r.status==='cancelled'){app.innerHTML=pageHead('Комната закрыта')+'<a class="button" href="#rooms">К комнатам</a>';return;}if(r.status==='lobby'){app.innerHTML=pageHead(r.name,`${s.city} · ${modes[r.mode]}`,`<span class="pill">Код ${r.id}</span>`)+`<div class="grid two"><section class="panel"><h2>Лобби</h2>${r.players.map(p=>`<div class="pick"><strong>${esc(p)}</strong><span class="pill">${r.ready[p]?'Готов':'Не готов'}</span></div>`).join('')}<div class="actions"><button data-action="ready">${r.ready[user.name]?'Отменить готовность':'Я готов'}</button>${r.host===user.name?'<button class="primary" data-action="start">Начать игру →</button>':''}<button data-action="leave" class="danger">${r.host===user.name?'Закрыть комнату':'Выйти'}</button></div></section><section class="panel"><span class="eyebrow">РАВНЫЕ УСЛОВИЯ</span><h2>${num(s.budget)} условных единиц</h2><p>${s.districts.length} районов · ${s.measures.length} мероприятий<br>Максимум 8 участников. Каждый управляет городом независимо.</p><p class="small">${esc(s.methodology)}</p></section></div>`;return;}if(r.status==='scored'||r.status==='complete'){app.innerHTML=pageHead('Решения приняты','Результаты зафиксированы. AI готовит разбор каждого сценария.')+`<div class="grid">${r.players.map(p=>`<article class="card"><h3>${esc(p)}</h3>${p===user.name||r.host===user.name&&(r.mode==='local'||r.mode==='ai')?`<a class="button primary" href="#result/${r.submitted[p]}">Открыть результат →</a>`:'<p>Результат доступен в таблице комнаты.</p>'}</article>`).join('')}</div><div id="room-ranking" class="panel"></div>`;loadRoomRanking(r.id);return;}
if(r.submitted[who]){app.innerHTML=pageHead('Ваш сценарий сохранён','Ждём остальных игроков. Решения больше нельзя менять.')+`<div class="panel">${r.players.map(p=>`<div class="pick">${esc(p)} <span class="pill">${r.submitted[p]?'Сдал решения':'Принимает решения'}</span></div>`).join('')}</div>`;return;}
if(r.mode==='local'&&handoff){app.innerHTML=`<div class="panel hand-off"><span class="eyebrow">ПЕРЕДАЙТЕ УПРАВЛЕНИЕ</span><div class="number">${r.players.indexOf(who)+1} / ${r.players.length}</div><h2>${esc(who)}</h2><p>Предыдущие решения скрыты. Каждый участник начинает с того же бюджета и исходных показателей.</p><button class="primary" data-action="handoff">Я готов — начать ход →</button></div>`;return;}
const spent=current.budget?.spent??0,remaining=current.budget?.remaining??s.budget;
app.innerHTML=pageHead(s.city,`${modes[r.mode]} · ${who}`,`<span class="pill">ROOM ${r.id}</span>`)+`<section class="budget">${stat(num(remaining),'Осталось из '+num(s.budget)+' усл. ед.')}<div><div class="row between"><strong>Единый виртуальный бюджет</strong><span>${num(spent)} потрачено</span></div><div class="meter"><progress max="${s.budget}" value="${spent}"></progress></div><span class="sub">Остаток не даёт бонуса к Score</span></div>${stat(picks.length+' / 5','Решений принято')}</section><div class="game-layout"><section><div class="tabs"><button data-action="filter" data-value="" class="${!filter?'active':''}">Все меры</button>${cats.map((c,i)=>`<button data-action="filter" data-value="${c}" class="${filter===c?'active':''}">${icons[i]} ${labels[i]}</button>`).join('')}</div><div class="measure-grid">${s.measures.filter(m=>!filter||m.category===filter).map(m=>{const selected=picks.some(p=>p.id===m.id);return `<article class="card ${selected?'selected':''}"><div class="row between"><span class="tag">${esc(m.id)} / ${esc(m.category)}</span><span class="pill">${m.cost} усл. ед.</span></div><h3>${esc(m.name)}</h3><p>${esc(m.type)} · лаг ${m.lag} кв. · горизонт 8 кв.</p><div class="effects">${Object.entries(m.effects).filter(([,v])=>v!==0).map(([k,v])=>`<span>${esc(k)} ${delta(v)}</span>`).join('')}</div><p class="small">Потенциальные эффекты до учёта лага.</p>${m.type==='Район'?`<label>Район<select data-target="${esc(m.id)}" ${selected?'disabled':''}><option value="">Выберите район</option>${s.districts.map(d=>`<option>${esc(d.name)}</option>`).join('')}</select></label>`:'<p class="small">Действует во всех районах</p>'}<button ${selected||picks.length===5?'disabled':''} data-action="choose" data-id="${esc(m.id)}" class="${selected?'':'primary'}">${selected?'✓ В сценарии':'Выбрать мероприятие +'}</button></article>`;}).join('')}</div></section><aside class="panel sidebar"><span class="eyebrow">ВАША СТРАТЕГИЯ</span><h3>Пять решений</h3>${picks.map((p,i)=>{const m=s.measures.find(m=>m.id===p.id);return `<div class="pick"><span class="ordinal">${i+1}</span><div><strong>${esc(m.name)}</strong><span class="muted">${esc(p.district||'Весь город')} · ${m.cost} ед.</span></div><button data-action="remove" data-id="${esc(p.id)}" aria-label="Убрать ${esc(m.name)}">×</button></div>`;}).join('')||'<p class="small">Выбирайте мероприятия из каталога. Бюджет и ограничения проверяет сервер.</p>'}<p class="small"><br>Ровно 5 мер. Максимум 2 из одного направления, минимум 3 направления.</p><button class="primary fullwidth" data-action="finish" ${picks.length!==5?'disabled':''}>Завершить и получить AI-отчёт →</button><p class="small"><br>После сдачи сценарий изменить нельзя.</p></aside></div><div class="section-title"><h2>Районы города</h2><span class="pill">${picks.length?'Ожидаемое состояние':'Исходные показатели'}</span></div>${districtCards(s,current.preview)}<details><summary>Методология и ограничения</summary><p>${esc(s.methodology)}</p><p>Лаг: эффект × (8 − L) / 8. Синергии M1+M2, M10+M12, M5+M6. Несовместимы M1+M3; M4+M7 и M5+M13 в одном районе. Финальный Score рассчитывается после сдачи пяти решений.</p></details>`;}
async function loadRoomRanking(id){try{const list=await api('/room-ranking/'+id);if($('#room-ranking'))$('#room-ranking').innerHTML='<h3>Таблица комнаты</h3>'+table(['Место','Игрок','Score','Статус'],list.map(x=>`<tr><td>${x.rank}</td><td>${esc(x.player)}</td><td>${num(x.score)}</td><td>${esc(statuses[x.status])}</td></tr>`));}catch(e){notice(e.message);}}
function exportsHTML(r){return r.status==='complete'?`<div class="actions">${['pdf','docx','json'].map(f=>`<a class="button ${f==='pdf'?'primary':''}" href="/api/results/${r.id}/${f}" download>↓ ${f==='docx'?'WORD':f.toUpperCase()}</a>`).join('')}</div>`:'';}
async function result(id){const r=await api('/results/'+id),f=r.facts;app.innerHTML=pageHead('Результат сценария',`${r.city} · ${r.player} · ${modes[r.mode]} · ${date(r.created)}`,`<a class="button" href="#room/${r.room_id}">В комнату</a>`)+`<section class="score-banner"><div><span class="eyebrow">ASTANA QUALITY OF LIFE SCORE</span><div class="big-score">${num(f.final.score)}</div><span class="positive">${delta(f.score_delta)} к исходному состоянию</span></div><div class="grid two">${stat(num(f.baseline.score),'Baseline Score')}${stat(r.rank?r.rank+' / '+r.players_count:'Ожидается','Место в комнате')}${stat(f.budget.spent+' / '+f.budget.initial,'Бюджет, усл. ед.')}${stat(f.budget.remaining,'Остаток, усл. ед.')}</div></section>${exportsHTML(r)}<section id="ai-report" class="panel"><span class="eyebrow">AI POST-GAME ANALYSIS</span>${r.ai_analysis?analysisHTML(r):`<h2>${esc(statuses[r.status])}</h2><p>${esc(r.error||'Расчёт сохранён. Игра будет завершена после готовности персонального AI-анализа.')}</p>${r.status==='analysis_failed'?`<button class="primary" data-action="retry" data-id="${r.id}">Повторить AI-анализ</button>`:'<div class="loading">Ожидаем результат</div>'}`}</section><div class="section-title"><h2>Пять управленческих решений</h2></div><div class="grid two">${f.decisions.map(d=>`<article class="card"><span class="tag">${esc(d.measure.id)} / ${esc(d.measure.category)}</span><h3>${esc(d.measure.name)}</h3><p>${esc(d.district||'Весь город')} · ${d.measure.cost} усл. ед.</p><div class="number positive">${delta(d.marginal_score)}</div><p class="small">Предельный вклад в Score: сравнение со сценарием без этой меры, включая её синергии.</p>${r.ai_analysis?`<p>${esc(r.ai_analysis.decisions[d.measure.id])}</p>`:''}<details><summary>Фактические эффекты в модели</summary>${d.changes_without_vs_with.filter(v=>v.delta.some(n=>n!==0)).map(v=>`<p class="small">${esc(v.name)}: ${v.delta.map((n,i)=>n!==0?esc(r.scenario.keys[i])+' '+delta(n):'').filter(Boolean).join(' · ')}</p>`).join('')}</details></article>`).join('')}</div><div class="section-title"><h2>Районы: до и после</h2></div><section class="panel">${table(['Район','До','После','Изменение','Сравнение'],f.final.districts.map(d=>`<tr><td>${esc(d.name)}</td><td>${num(d.before_score)}</td><td>${num(d.score)}</td><td class="positive">${delta(d.score_delta)}</td><td><div class="chart-bars"><progress max="100" value="${d.before_score}" title="До"></progress><progress max="100" value="${d.score}" title="После"></progress></div></td></tr>`))}${f.final.districts.map(d=>`<details><summary>${esc(d.name)} · все 10 индикаторов</summary>${table(['Показатель','До','После','Δ'],d.before.map((v,i)=>`<tr><td>${esc(r.scenario.keys[i])} · ${indicators[i]}</td><td>${num(v)}</td><td>${num(d.after[i])}</td><td>${delta(d.delta[i])}</td></tr>`))}${r.ai_analysis?`<p>${esc(r.ai_analysis.districts[d.name])}</p>`:''}</details>`).join('')}</section><div class="section-title"><h2>Механика результата</h2></div><div class="grid two"><section class="panel"><h3>Синергии</h3>${f.final.synergies.length?f.final.synergies.map(s=>`<p>${s.measures.map(esc).join(' + ')} → ${esc(s.district)} / ${esc(s.indicator)} +${s.effect}</p>`).join(''):'<p>В выбранном наборе нет активных синергий.</p>'}<h3>Критические показатели</h3>${f.final.critical_indicators.map(c=>`<p class="small">${esc(c.district)} / ${esc(c.indicator)}: ${num(c.value)}</p>`).join('')||'<p>Показателей ниже 40 нет.</p>'}</section><section class="panel"><h3>Технический разбор</h3><p>0,7 × среднее по населению + 0,3 × слабейший район − число индикаторов ниже 40.</p><p>Среднее: ${num(f.final.weighted_average)}<br>Минимум: ${num(f.final.minimum_district)}<br>Штраф: ${f.final.critical_indicators.length}</p><p class="small">Вклады отдельных мер не суммируются из-за синергий и нелинейной формулы.</p><p class="small">${esc(r.scenario.methodology)}</p></section></div><section class="report-block"><h3>Проверенные альтернативы</h3>${f.verified_alternatives.map(a=>`<div class="panel"><p>${a.picks.map(p=>esc(p.id)+' / '+esc(p.district||'город')).join(' · ')}</p><strong>Score ${num(a.score)} (${delta(a.improvement)}) · ${a.cost} усл. ед.</strong></div>`).join('')||'<p>Улучшающих замен одного решения не найдено. Это не доказательство глобального оптимума.</p>'}</section>`;if(['analyzing','waiting_players'].includes(r.status))timer=setTimeout(()=>{if(location.hash==='#result/'+id)result(id).catch(e=>notice(e.message));},3000);}
function analysisHTML(r){const a=r.ai_analysis;return `<h2>Ваша стратегия под микроскопом</h2><p>${esc(a.summary)}</p>${[['Что вы сделали правильно',a.what_you_did_right],['Что можно было сделать лучше',a.what_you_did_wrong],['Компромиссы',a.tradeoffs],['Основные риски',a.risks],['Рекомендации на следующую игру',a.recommendations]].map(([t,list])=>`<section class="report-block"><h3>${t}</h3><ul>${list.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></section>`).join('')}<p class="small">Модель: ${esc(r.ai_model)}. AI объясняет серверные расчёты; текст может требовать проверки.</p>`;}
async function history(){const rows=await api('/history');app.innerHTML=pageHead('История игр','Сохранённые результаты и отчёты. Скачивание не запускает AI повторно.')+`<section class="panel">${rows.length?table(['Дата','Город / игрок','Режим','Score','Место','Статус','Отчёт'],rows.map(r=>`<tr><td>${date(r.created)}</td><td>${esc(r.city)}<br>${esc(r.player)}</td><td>${esc(modes[r.mode])}</td><td>${num(r.facts.final.score)}</td><td>${r.rank||'—'} / ${r.players_count}</td><td>${esc(statuses[r.status])}</td><td><a class="button" href="#result/${r.id}">Открыть</a>${exportsHTML(r)}</td></tr>`)):'<div class="empty">Ваш первый сценарий ещё впереди. <a href="#rooms">Начать игру →</a></div>'}</section>`;}
async function leaderboard(){const rows=await api('/leaderboard');app.innerHTML=pageHead('Рейтинг акимов','Главный критерий — победы. При равном Score участники делят место.')+`<section class="panel">${table(['Место','Игрок','Победы','Игр','Побед, %','Средний Score','Лучший Score'],rows.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.name)}</td><td>${r.wins}</td><td>${r.games}</td><td>${num(r.win_rate)}</td><td>${num(r.average)}</td><td>${num(r.best)}</td></tr>`))}<p class="small">Учитываются завершённые AI-отчёты. Одиночные игры не дают побед; локальные гости и боты не участвуют в глобальном рейтинге.</p></section>`;}
async function profile(){const p=await api('/profile');app.innerHTML=pageHead('Профиль',p.name)+`<div class="grid four">${[['Игр',p.stats.games],['Побед',p.stats.wins],['Средний Score',num(p.stats.average)],['Лучший Score',num(p.stats.best)]].map(([l,v])=>`<div class="panel">${stat(v,l)}</div>`).join('')}</div><div class="section-title"><h2>Личные данные</h2></div><div class="grid two"><form id="profile-form" class="panel stack"><label>Отображаемое имя<input name="display_name" maxlength="100" value="${esc(p.display_name)}"></label><label>Email<input name="email" type="email" value="${esc(p.email)}"></label><label>Аватар — символ или эмодзи<input name="avatar" maxlength="2" value="${esc(p.avatar)}"></label><button class="primary">Сохранить профиль</button></form><form id="password-form" class="panel stack"><h3>Сменить пароль</h3><label>Текущий пароль<input type="password" name="old" autocomplete="current-password" required></label><label>Новый пароль<input type="password" name="new" minlength="12" maxlength="256" autocomplete="new-password" required></label><button>Сменить пароль и выйти</button><button type="button" data-action="logout" class="danger">Выйти из аккаунта</button></form></div>`;}
async function admin(){if(user.role!=='admin')throw new Error('Нет доступа к панели администратора');const data=await api('/admin/overview');templates=await api('/cities');const template=templates.find(t=>t.id===editingID)||templates[0];editingID=template.id;editor=structuredClone(template.scenario);app.innerHTML=pageHead('Управление симулятором','Изменения шаблона применяются только к новым комнатам.')+`<div class="grid four">${[['Пользователей',data.stats.users],['Игр',data.stats.games],['Активных комнат',data.stats.active_rooms],['Средний Score',num(data.stats.average_score)]].map(([l,v])=>`<div class="panel">${stat(v,l)}</div>`).join('')}</div><div class="section-title"><h2>Шаблоны городов</h2><button data-action="new-template">Новый шаблон +</button></div><section class="panel"><label>Редактируемый шаблон<select id="admin-template">${templates.map(t=>`<option value="${t.id}" ${t.id===editingID?'selected':''}>${esc(t.scenario.city)}${t.archived?' · архив':''}</option>`).join('')}</select></label><div id="city-editor">${editorHTML()}</div><div class="actions"><button data-action="save-template" class="primary">Сохранить шаблон</button>${editingID!=='default'?`<button data-action="archive-template">${template.archived?'Вернуть из архива':'В архив'}</button><button class="danger" data-action="delete-template">Удалить шаблон</button>`:''}</div></section><div class="section-title"><h2>Пользователи</h2></div><section class="panel">${table(['Логин','Роль','Email'],data.users.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.role)}</td><td>${esc(u.email)}</td></tr>`))}</section><div class="section-title"><h2>Комнаты и игры</h2><span class="muted">В среднем ${num(data.stats.average_players)} игрока</span></div><section class="panel">${table(['Код','Название','Игроки','Статус','Действие'],data.rooms.map(r=>`<tr><td>${r.id}</td><td>${esc(r.name)}</td><td>${r.players.length}</td><td>${esc(statuses[r.status])}</td><td><a class="button" href="#room/${r.id}">Открыть</a></td></tr>`))}</section><div class="section-title"><h2>Отчёты всех игр</h2><a class="button" href="#history">Просмотреть результаты →</a></div>`;}
async function route(){routeVersion++;const version=routeVersion;if(roomSocket){const old=roomSocket;roomSocket=null;old.onclose=null;old.close();}clearTimeout(timer);timer=null;current=null;notice('');nav();const [page='home',id]=(location.hash.slice(1)||'home').split('/');if(!user&&!['home','login','register'].includes(page)){location.hash='login';return;}app.innerHTML='<div class="loading">Загружаем…</div>';try{if(page==='home')home();else if(page==='login'||page==='register')auth(page==='register');else if(page==='rooms')await rooms();else if(page==='create')await create();else if(page==='room')await openRoom(id);else if(page==='result')await result(id);else if(page==='history')await history();else if(page==='leaderboard')await leaderboard();else if(page==='profile')await profile();else if(page==='admin')await admin();else home();}catch(e){if(version===routeVersion){app.innerHTML='<div class="empty">Не удалось загрузить страницу. <button data-action="refresh">Повторить</button></div>';notice(e.message);}}}
async function action(el){const a=el.dataset.action;if(a==='refresh')return route();if(a==='filter'){filter=el.dataset.value;renderRoom();return;}if(a==='handoff'){handoff=false;renderRoom();return;}if(a==='join'){await api('/rooms/'+el.dataset.id+'/join','POST');location.hash='room/'+el.dataset.id;return;}if(['ready','start','leave'].includes(a)){current=await api('/rooms/'+current.room.id+'/'+a,'POST');if(a==='leave')location.hash='rooms';else renderRoom();return;}if(a==='choose'||a==='remove'){const p=[...(current.picks||[])];if(a==='choose'){const m=current.room.scenario.measures.find(m=>m.id===el.dataset.id);const target=[...document.querySelectorAll('[data-target]')].find(e=>e.dataset.target===m.id);p.push({id:m.id,district:target?.value||''});}else{p.splice(p.findIndex(x=>x.id===el.dataset.id),1);}current=await api('/rooms/'+current.room.id+'/decisions','POST',{picks:p});renderRoom();return;}if(a==='finish'){if(!confirm('Зафиксировать пять решений? После сдачи изменить их нельзя.'))return;current=await api('/rooms/'+current.room.id+'/submit','POST');handoff=true;renderRoom();return;}if(a==='retry'){await api('/results/'+el.dataset.id+'/retry','POST');await result(el.dataset.id);return;}if(a==='logout'){await api('/logout','POST');user=null;location.hash='home';await route();return;}if(a==='generate-city'){notice('AI создаёт учебный город…',true);editor=await api('/cities/generate','POST',{theme:$('#city-theme').value});$('#city-editor').innerHTML=editorHTML();$('#city-editor').hidden=false;notice('Город прошёл серверную проверку. Проверьте его перед созданием комнаты.',true);return;}if(a==='add-district'){editor.districts.push({name:'Новый район',pop:0,v:Array(10).fill(50),facilities:[]});}else if(a==='remove-district'){editor.districts.splice(Number(el.dataset.index),1);}else if(a==='add-measure'){editor.measures.push({id:'NEW'+(editor.measures.length+1),name:'Новое мероприятие',category:cats[0],type:'Район',cost:10,lag:1,effects:{}});}else if(a==='remove-measure'){editor.measures.splice(Number(el.dataset.index),1);}else if(a==='new-template'){editingID='';editor=structuredClone(templates[0].scenario);editor.city='Новый город';$('#admin-template').value='';$('#city-editor').innerHTML=editorHTML();return;}else if(a==='save-template'||a==='archive-template'){if(editingID==='default'){editor=await api('/scenario','PUT',editor);}else{const old=templates.find(t=>t.id===editingID);const v=await api('/admin/cities',editingID?'PUT':'POST',{id:editingID,scenario:editor,archived:a==='archive-template'?!old.archived:(old?.archived||false)});editingID=v.id;}notice('Шаблон сохранён. Уже созданные комнаты не изменены.',true);await admin();return;}else if(a==='delete-template'){if(!confirm('Удалить шаблон? Сохранённые игры останутся доступны.'))return;await api('/admin/cities/'+editingID,'DELETE');editingID='default';await admin();return;}else{return;}$('#city-editor').innerHTML=editorHTML();}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||busy)return;busy=true;el.disabled=true;try{notice('');await action(el);}catch(err){notice(err.message);}finally{busy=false;el.disabled=false;}});
document.addEventListener('input',e=>{if(e.target.dataset.edit){const path=e.target.dataset.edit.split('.');let obj=editor;for(const k of path.slice(0,-1))obj=obj[k];obj[path.at(-1)]=e.target.type==='number'?Number(e.target.value):e.target.value;}if(e.target.dataset.facilities!==undefined)editor.districts[Number(e.target.dataset.facilities)].facilities=e.target.value.split('\n').filter(Boolean);});
document.addEventListener('change',async e=>{if(e.target.id==='mode')$('#local-count').hidden=e.target.value!=='local';if(e.target.id==='source'){$('#city-editor').hidden=e.target.value==='template';$('#ai-city').hidden=e.target.value!=='generated';$('#template-label').hidden=e.target.value!=='template';}if(e.target.id==='city-template'){editor=structuredClone(templates.find(t=>t.id===e.target.value).scenario);$('#city-editor').innerHTML=editorHTML();$('#source-note').textContent=editor.methodology;}if(e.target.id==='admin-template'){editingID=e.target.value;try{await admin();}catch(err){notice(err.message);}}});
document.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;const form=e.target,button=form.querySelector('button[type=submit],button:not([type])');busy=true;if(button)button.disabled=true;const data=Object.fromEntries(new FormData(form));try{notice('');if(form.id==='auth-form'){user=await api('/'+form.dataset.mode,'POST',data);location.hash='rooms';}else if(form.id==='join-form'){const id=data.code.trim().toLowerCase();await api('/rooms/'+encodeURIComponent(id)+'/join','POST');location.hash='room/'+id;}else if(form.id==='create-form'){data.players=Number(data.players);if(data.source!=='template')data.scenario=editor;const v=await api('/rooms','POST',data);location.hash='room/'+v.room.id;}else if(form.id==='profile-form'){await api('/profile','PATCH',data);notice('Профиль сохранён.',true);}else if(form.id==='password-form'){await api('/profile/password','POST',data);user=null;location.hash='login';}}catch(err){notice(err.message);}finally{busy=false;if(button)button.disabled=false;}});
window.addEventListener('hashchange',route);
api('/me').then(v=>{user=v;}).catch(()=>{}).finally(route);
